import org.elasticsearch.action.admin.indices.alias.IndicesAliasesRequest;
import org.elasticsearch.action.bulk.BulkRequest;
import org.elasticsearch.action.index.IndexRequest;
import org.elasticsearch.client.RequestOptions;
import org.elasticsearch.client.RestHighLevelClient;
import org.elasticsearch.common.xcontent.XContentType;

public class SearchIndexManager {
    private final RestHighLevelClient client;

    public SearchIndexManager(RestHighLevelClient client) {
        this.client = client;
    }

    public void executeBulkBatch(String indexName, java.util.List<String> jsonDocuments) throws java.io.IOException {
        BulkRequest bulkRequest = new BulkRequest();
        for (String jsonDoc : jsonDocuments) {
            bulkRequest.add(new IndexRequest(indexName).source(jsonDoc, XContentType.JSON));
        }
        // Execute synchronous bulk ingestion; production should handle retries for 429 Too Many Requests
        client.bulk(bulkRequest, RequestOptions.DEFAULT);
    }

    public void atomicAliasSwap(String oldIndex, String newIndex, String aliasName) throws java.io.IOException {
        IndicesAliasesRequest request = new IndicesAliasesRequest();
        IndicesAliasesRequest.AliasActions addAction = 
            new IndicesAliasesRequest.AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
                .index(newIndex)
                .alias(aliasName);

        IndicesAliasesRequest.AliasActions removeAction = 
            new IndicesAliasesRequest.AliasActions(IndicesAliasesRequest.AliasActions.Type.REMOVE)
                .index(oldIndex)
                .alias(aliasName);

        request.addAliasAction(addAction);
        request.addAliasAction(removeAction);

        client.indices().updateAliases(request, RequestOptions.DEFAULT);
    }
}
